stat -c 'env_owner=%U env_group=%G env_mode=%a' /etc/inventory-db.env; if [ -r /etc/inventory-db.env ]; then printf 'unprivileged_readable=yes\n'; exit 1; else printf 'unprivileged_readable=no\n'; fi; sudo -n sed -n '/^DB_PASSWORD=[REDACTED] /etc/inventory-db.env; sudo -n mysql --batch --raw --skip-column-names <<'ROOT_SQL'
SELECT CONCAT('schema_exists=', COUNT(*)) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='inventory';
SELECT CONCAT('account=',User,'@',Host,',has_password=[REDACTED]','yes','no')) FROM mysql.user WHERE User='inventory_app';
SELECT CONCAT('db_grants=',User,'@',Host,':',Db,':',Select_priv,Insert_priv,Update_priv,Delete_priv) FROM mysql.db WHERE User='inventory_app' AND Db='inventory';
SHOW CREATE TABLE inventory.items;
ROOT_SQL
sudo -n /bin/sh -c '. /etc/inventory-db.env; MYSQL_PWD=$DB_PASSWORD; export MYSQL_PWD; exec mysql --protocol=socket --batch --raw --skip-column-names -u "$DB_USER" "$DB_NAME"' <<'APP_SQL'
SELECT CONCAT('authenticated_as=',CURRENT_USER());
SELECT CONCAT('selected_database=',DATABASE());
START TRANSACTION;
INSERT INTO items (sku,name,quantity) VALUES ('__inventory_verification__','Verification item',1) ON DUPLICATE KEY UPDATE name=VALUES(name),quantity=VALUES(quantity);
SELECT CONCAT('inserted_row=',sku,':',name,':',quantity) FROM items WHERE sku='__inventory_verification__';
UPDATE items SET quantity=2 WHERE sku='__inventory_verification__';
SELECT CONCAT('updated_quantity=',quantity) FROM items WHERE sku='__inventory_verification__';
DELETE FROM items WHERE sku='__inventory_verification__';
COMMIT;
SELECT CONCAT('verification_rows_after_cleanup=',COUNT(*)) FROM items WHERE sku='__inventory_verification__';
APP_SQL

